#include <stdio.h>
#include <string.h>

int main(void) {
    char s[256];
    if (scanf("%255s", s) != 1) s[0] = '\0';
    int len = (int)strlen(s);

    /* naipes: 0=Copas, 1=Espadas, 2=Ouros, 3=Paus (ordem exigida na saída) */
    int seen[4][14];
    int dup[4] = {0, 0, 0, 0};
    memset(seen, 0, sizeof(seen));

    for (int i = 0; i + 2 < len; i += 3) {
        int v = (s[i] - '0') * 10 + (s[i + 1] - '0'); /* valor 01..13 */
        int n;
        switch (s[i + 2]) {
            case 'C': n = 0; break;
            case 'E': n = 1; break;
            case 'U': n = 2; break;
            default:  n = 3; break; /* 'P' */
        }
        if (seen[n][v]) dup[n] = 1;
        seen[n][v] = 1;
    }

    for (int n = 0; n < 4; n++) {
        if (dup[n]) {
            printf("erro\n");
        } else {
            int cnt = 0;
            for (int v = 1; v <= 13; v++)
                if (seen[n][v]) cnt++;
            printf("%d\n", 13 - cnt);
        }
    }
    return 0;
}
